func mustItems(t *testing.T, pairs ...string) map[string]json.RawMessage {
	t.Helper()
	if len(pairs)%2 != 0 {
		t.Fatalf("pairs must alternate name/value")
	}
	items := map[string]json.RawMessage{}
	for i := 0; i < len(pairs); i += 2 {
